-- =============================================================================
-- NGÂN HÀNG CÂU HỎI JPD113 / JPD123
-- =============================================================================
-- display_order: 1 trở lên cho luyện tập, 1001 trở lên cho mini test,
-- 2001–2050 cho 50 câu của từng kỹ năng trong ngân hàng kiểm tra chương.
START TRANSACTION;

-- NGỮ PHÁP — dữ liệu câu hỏi theo bài.

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 1 (N1 は N2 です。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'田中さんは教師です。') AS content, _utf8mb4'「です」 — Câu khẳng định danh từ.' AS explanation, _utf8mb4'{"options":{"A":"Tanaka từng là giáo viên.","B":"Yamada là giáo viên.","C":"Tanaka là bác sĩ.","D":"Tanaka là giáo viên."},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Linh là nhân viên cửa hàng.', _utf8mb4 0x0a, _utf8mb4'リンさんは店員（　）。'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"です","B":"でした","C":"ではありません","D":"ですか"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Hải là nhân viên ngân hàng.'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"ハイさんは銀行員ですか。","B":"ハイさんは銀行員です。","C":"ハイさんは銀行員でした。","D":"ハイさんは銀行員ではありません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'アンさんは料理人です。'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"Lan là đầu bếp.","B":"An là sinh viên.","C":"An là đầu bếp.","D":"An từng là đầu bếp."},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Lan là đầu bếp.', _utf8mb4 0x0a, _utf8mb4'ランさんは料理人（　）。'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"でした","B":"ではありません","C":"ですか","D":"です"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Tanaka là đầu bếp.'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"田中さんは料理人です。","B":"田中さんは料理人でした。","C":"田中さんは料理人ではありません。","D":"田中さんは料理人ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'リンさんは銀行員です。'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"Linh là đầu bếp.","B":"Linh là nhân viên ngân hàng.","C":"Linh từng là nhân viên ngân hàng.","D":"Hải là nhân viên ngân hàng."},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Nam là nhân viên công ty.', _utf8mb4 0x0a, _utf8mb4'ナムさんは会社員（　）。'), _utf8mb4'「です」 — Câu khẳng định danh từ.', _utf8mb4'{"options":{"A":"ではありません","B":"ですか","C":"です","D":"でした"},"correctAnswer":"C"}'
