    UNION ALL SELECT 2045, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Yamada là sinh viên của Đại học Kyushu.', _utf8mb4 0x0a, _utf8mb4'山田さんは九州大学（　）学生です。'), CONCAT(_utf8mb4'Trợ từ の – quan hệ sở thuộc. 山田さんは九州大学の学生です。', _utf8mb4 0x0a, _utf8mb4'Yamada là sinh viên của Đại học Kyushu.'), _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"で"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 の N3 です。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 6 (N は なんですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Khi được hỏi sở thích của mình là gì, Tanaka trả lời “nấu ăn”.') AS content, _utf8mb4'「何」 — Hỏi cái gì, sự việc gì.' AS explanation, _utf8mb4'{"options":{"A":"「田中さんの趣味は何ですか。」「料理です。」","B":"「田中さんの趣味はいつですか。」「料理です。」","C":"「田中さんの趣味は何人ですか。」「料理です。」","D":"「田中さんの趣味はどなたですか。」「料理です。」"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「リンさんの趣味は何ですか。」「テニスです。」'), _utf8mb4'「何」 — Hỏi cái gì, sự việc gì.', _utf8mb4'{"options":{"A":"Khi được hỏi sở thích của mình là gì, Linh trả lời “xem phim”.","B":"Khi được hỏi sở thích của mình là gì, Linh trả lời “quần vợt”.","C":"Khi được hỏi khi nào sẽ thi, Linh trả lời “quần vợt”.","D":"Khi được hỏi sở thích của mình là gì, Hải trả lời “quần vợt”."},"correctAnswer":"B"}'
