) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 です。N3 も N2 です。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 1 (N は số + かいです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'案内板によると、会議室は二階です。') AS content, _utf8mb4'「です」 — Nói vị trí tầng.' AS explanation, _utf8mb4'{"options":{"A":"Theo bảng chỉ dẫn, phòng họp nằm ở tầng hai.","B":"Theo bảng chỉ dẫn, phòng họp không nằm ở tầng hai.","C":"Theo bảng chỉ dẫn, quầy lễ tân nằm ở tầng hai.","D":"Theo bảng chỉ dẫn, phòng họp nằm ở tầng ba."},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Theo bảng chỉ dẫn, văn phòng nằm ở tầng sáu.', _utf8mb4 0x0a, _utf8mb4'案内板によると、事務室は六階（　）。'), _utf8mb4'「です」 — Nói vị trí tầng.', _utf8mb4'{"options":{"A":"ですか","B":"です","C":"でしたか","D":"ではありません"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Theo bảng chỉ dẫn, phòng nghỉ nằm ở tầng bảy.'), _utf8mb4'「です」 — Nói vị trí tầng.', _utf8mb4'{"options":{"A":"案内板によると、休憩室は七階ではありません。","B":"案内板によると、休憩室は七階ですか。","C":"案内板によると、休憩室は七階です。","D":"案内板によると、休憩室は七階でしたか。"},"correctAnswer":"C"}'
