    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Theo bảng chỉ dẫn, nhà ăn nằm ở tầng tám.', _utf8mb4 0x0a, _utf8mb4'案内板によると、食堂は八階（　）。'), _utf8mb4'「です」 — Nói vị trí tầng.', _utf8mb4'{"options":{"A":"です","B":"でしたか","C":"ではありません","D":"ですか"},"correctAnswer":"A"}'
