    UNION ALL SELECT 2042, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'リンさんは遠くの建物を指して「受付はあちらです」と案内しました。'), CONCAT(_utf8mb4'Chỉ phương hướng lịch sự. リンさんは遠くの建物を指して「受付はあちらです」と案内しました。', _utf8mb4 0x0a, _utf8mb4'Linh chỉ tòa nhà đằng kia, xa cả hai người để chỉ đường đến quầy lễ tân.'), _utf8mb4'{"options":{"A":"Linh chỉ tòa nhà đằng kia, xa cả hai người để chỉ đường đến quầy lễ tân.","B":"Linh chỉ tòa nhà ngay sát người nói để chỉ đường đến quầy lễ tân.","C":"Linh chỉ tòa nhà đằng kia, xa cả hai người để chỉ đường đến quầy bán hàng.","D":"Hải chỉ tòa nhà đằng kia, xa cả hai người để chỉ đường đến quầy lễ tân."},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 6 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は こちら／そちら／あちらです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 7 (N は どちらですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'田中さんは受付で「すみません、食堂はどちらですか」と聞きました。') AS content, _utf8mb4'「どちら」 — Hỏi vị trí lịch sự.' AS explanation, _utf8mb4'{"options":{"A":"Tại quầy lễ tân, Yamada hỏi lịch sự đường đến nhà ăn.","B":"Tại quầy lễ tân, Tanaka hỏi lịch sự đường đến phòng họp.","C":"Tại quầy lễ tân, Tanaka hỏi lịch sự đường đến nhà ăn.","D":"Tại quầy lễ tân, Tanaka hỏi lịch sự giờ đóng cửa của nhà ăn."},"correctAnswer":"C"}' AS answers
