    UNION ALL SELECT 2043, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tại quầy lễ tân, Tanaka hỏi lịch sự đường đến phòng nghỉ.', _utf8mb4 0x0a, _utf8mb4'田中さんは受付で「すみません、休憩室は（　）ですか」と聞きました。'), CONCAT(_utf8mb4'Hỏi vị trí lịch sự. 田中さんは受付で「すみません、休憩室はどちらですか」と聞きました。', _utf8mb4 0x0a, _utf8mb4'Tại quầy lễ tân, Tanaka hỏi lịch sự đường đến phòng nghỉ.'), _utf8mb4'{"options":{"A":"いくつ","B":"どちら","C":"どなた","D":"いつ"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は どちらですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 8 (これ／それ／あれ は N です。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ランさんは手に持っている物を見せて「これは辞書です」と言いました。') AS content, _utf8mb4'「これ」 — Đại từ chỉ thị.' AS explanation, _utf8mb4'{"options":{"A":"Lan cho xem vật đặt ở xa cả hai người và nói đó là từ điển.","B":"Lan cho xem vật đang cầm trong tay và nói đó là ví tiền.","C":"Tanaka cho xem vật đang cầm trong tay và nói đó là từ điển.","D":"Lan cho xem vật đang cầm trong tay và nói đó là từ điển."},"correctAnswer":"D"}' AS answers
