    UNION ALL SELECT 2049, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Món ăn nhẹ hôm nay là nước ép làm từ nho.', _utf8mb4 0x0a, _utf8mb4'今日のおやつはぶどう（　）ジュースです。'), CONCAT(_utf8mb4'Trợ từ の – nguyên liệu. 今日のおやつはぶどうのジュースです。', _utf8mb4 0x0a, _utf8mb4'Món ăn nhẹ hôm nay là nước ép làm từ nho.'), _utf8mb4'{"options":{"A":"を","B":"へ","C":"まで","D":"の"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 13 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 の N2' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 14 (N1 は なんの N2 ですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「これは何のゼリーですか。」「いちごを使いました。」') AS content, _utf8mb4'「何の」 — Hỏi nguyên liệu.' AS explanation, _utf8mb4'{"options":{"A":"Người hỏi muốn biết thạch được làm từ nguyên liệu gì và được biết nguyên liệu là chuối.","B":"Người hỏi muốn biết thạch được làm từ nguyên liệu gì và được biết nguyên liệu là dâu tây.","C":"Người hỏi muốn biết thạch được làm cho người nào và được biết nguyên liệu là dâu tây.","D":"Người hỏi muốn biết kem sorbet được làm từ nguyên liệu gì và được biết nguyên liệu là dâu tây."},"correctAnswer":"B"}' AS answers
