    UNION ALL SELECT 2034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'お土産にフランスの車を買いました。'), CONCAT(_utf8mb4'Trợ từ の – nguồn gốc, xuất xứ. お土産にフランスの車を買いました。', _utf8mb4 0x0a, _utf8mb4'Tôi mua ô tô có xuất xứ từ Pháp làm quà.'), _utf8mb4'{"options":{"A":"Tôi mua túi xách có xuất xứ từ Pháp làm quà.","B":"Tôi mua ô tô có xuất xứ từ Pháp làm quà.","C":"Tôi mua ô tô để gửi sang Pháp làm quà.","D":"Tôi mua ô tô có xuất xứ từ Canada làm quà."},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 16 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 の N2' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 17 (N を số lượng (～つ) ください。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi hai phần bánh ngọt.', _utf8mb4 0x0a, _utf8mb4'ケーキを二つ（　）。') AS content, _utf8mb4'「ください」 — Yêu cầu số lượng.' AS explanation, _utf8mb4'{"options":{"A":"ください","B":"います","C":"行きます","D":"来ます"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi sáu phần bánh mì kẹp.'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"サンドイッチを六つ来ます。","B":"サンドイッチを六つください。","C":"サンドイッチを六ついます。","D":"サンドイッチを六つ行きます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'アイスを七つください。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"Vui lòng cho tôi bảy phần bánh pudding.","B":"Vui lòng cho tôi tám phần kem.","C":"Vui lòng cho tôi bảy phần kem.","D":"Tôi đã trả lại bảy phần kem."},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi tám phần táo.', _utf8mb4 0x0a, _utf8mb4'りんごを八つ（　）。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"います","B":"行きます","C":"来ます","D":"ください"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi tám phần quýt.'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"みかんを八つください。","B":"みかんを八ついます。","C":"みかんを八つ行きます。","D":"みかんを八つ来ます。"},"correctAnswer":"A"}'
