    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bảy phần cơm nắm.'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"おにぎりを七つ行きます。","B":"おにぎりを七つ来ます。","C":"おにぎりを七つください。","D":"おにぎりを七ついます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'おにぎりを六つください。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"Tôi đã trả lại sáu phần cơm nắm.","B":"Vui lòng cho tôi sáu phần bánh mì kẹp.","C":"Vui lòng cho tôi bảy phần cơm nắm.","D":"Vui lòng cho tôi sáu phần cơm nắm."},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi tám phần bánh mì kẹp.', _utf8mb4 0x0a, _utf8mb4'サンドイッチを八つ（　）。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"ください","B":"います","C":"行きます","D":"来ます"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi năm phần cơm nắm.'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"おにぎりを五つ来ます。","B":"おにぎりを五つください。","C":"おにぎりを五ついます。","D":"おにぎりを五つ行きます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'プリンを三つください。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"Vui lòng cho tôi ba phần táo.","B":"Vui lòng cho tôi bốn phần bánh pudding.","C":"Vui lòng cho tôi ba phần bánh pudding.","D":"Tôi đã trả lại ba phần bánh pudding."},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi một phần bánh ngọt.', _utf8mb4 0x0a, _utf8mb4'ケーキを一つ（　）。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"います","B":"行きます","C":"来ます","D":"ください"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bốn phần cơm nắm.'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"おにぎりを四つください。","B":"おにぎりを四ついます。","C":"おにぎりを四つ行きます。","D":"おにぎりを四つ来ます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'アイスを八つください。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"Vui lòng cho tôi một phần kem.","B":"Vui lòng cho tôi tám phần kem.","C":"Tôi đã trả lại tám phần kem.","D":"Vui lòng cho tôi tám phần bánh pudding."},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi ba phần cơm nắm.', _utf8mb4 0x0a, _utf8mb4'おにぎりを三つ（　）。'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"行きます","B":"来ます","C":"ください","D":"います"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bảy phần bánh mì.'), _utf8mb4'「ください」 — Yêu cầu số lượng.', _utf8mb4'{"options":{"A":"パンを七ついます。","B":"パンを七つ行きます。","C":"パンを七つ来ます。","D":"パンを七つください。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'おにぎりを二つください。'), CONCAT(_utf8mb4'Yêu cầu số lượng. おにぎりを二つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi hai phần cơm nắm.'), _utf8mb4'{"options":{"A":"Vui lòng cho tôi hai phần cơm nắm.","B":"Tôi đã trả lại hai phần cơm nắm.","C":"Vui lòng cho tôi hai phần bánh mì kẹp.","D":"Vui lòng cho tôi ba phần cơm nắm."},"correctAnswer":"A"}'
    UNION ALL SELECT 1011, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi tám phần bánh pudding.', _utf8mb4 0x0a, _utf8mb4'プリンを八つ（　）。'), CONCAT(_utf8mb4'Yêu cầu số lượng. プリンを八つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi tám phần bánh pudding.'), _utf8mb4'{"options":{"A":"来ます","B":"ください","C":"います","D":"行きます"},"correctAnswer":"B"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi ba phần quýt.'), CONCAT(_utf8mb4'Yêu cầu số lượng. みかんを三つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi ba phần quýt.'), _utf8mb4'{"options":{"A":"みかんを三つ行きます。","B":"みかんを三つ来ます。","C":"みかんを三つください。","D":"みかんを三ついます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'おにぎりを一つください。'), CONCAT(_utf8mb4'Yêu cầu số lượng. おにぎりを一つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi một phần cơm nắm.'), _utf8mb4'{"options":{"A":"Tôi đã trả lại một phần cơm nắm.","B":"Vui lòng cho tôi một phần bánh mì kẹp.","C":"Vui lòng cho tôi hai phần cơm nắm.","D":"Vui lòng cho tôi một phần cơm nắm."},"correctAnswer":"D"}'
    UNION ALL SELECT 1029, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi một phần kem.', _utf8mb4 0x0a, _utf8mb4'アイスを一つ（　）。'), CONCAT(_utf8mb4'Yêu cầu số lượng. アイスを一つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi một phần kem.'), _utf8mb4'{"options":{"A":"ください","B":"います","C":"行きます","D":"来ます"},"correctAnswer":"A"}'
    UNION ALL SELECT 1035, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bốn phần táo.'), CONCAT(_utf8mb4'Yêu cầu số lượng. りんごを四つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bốn phần táo.'), _utf8mb4'{"options":{"A":"りんごを四つ来ます。","B":"りんごを四つください。","C":"りんごを四ついます。","D":"りんごを四つ行きます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ケーキを七つください。'), CONCAT(_utf8mb4'Yêu cầu số lượng. ケーキを七つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bảy phần bánh ngọt.'), _utf8mb4'{"options":{"A":"Vui lòng cho tôi bảy phần bánh mì.","B":"Vui lòng cho tôi tám phần bánh ngọt.","C":"Vui lòng cho tôi bảy phần bánh ngọt.","D":"Tôi đã trả lại bảy phần bánh ngọt."},"correctAnswer":"C"}'
    UNION ALL SELECT 1047, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi sáu phần bánh mì.', _utf8mb4 0x0a, _utf8mb4'パンを六つ（　）。'), CONCAT(_utf8mb4'Yêu cầu số lượng. パンを六つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi sáu phần bánh mì.'), _utf8mb4'{"options":{"A":"います","B":"行きます","C":"来ます","D":"ください"},"correctAnswer":"D"}'
    UNION ALL SELECT 2017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'りんごを七つください。'), CONCAT(_utf8mb4'Yêu cầu số lượng. りんごを七つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi bảy phần táo.'), _utf8mb4'{"options":{"A":"Vui lòng cho tôi tám phần táo.","B":"Vui lòng cho tôi bảy phần táo.","C":"Tôi đã trả lại bảy phần táo.","D":"Vui lòng cho tôi bảy phần quýt."},"correctAnswer":"B"}'
    UNION ALL SELECT 2035, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi năm phần bánh mì.', _utf8mb4 0x0a, _utf8mb4'パンを五つ（　）。'), CONCAT(_utf8mb4'Yêu cầu số lượng. パンを五つください。', _utf8mb4 0x0a, _utf8mb4'Vui lòng cho tôi năm phần bánh mì.'), _utf8mb4'{"options":{"A":"行きます","B":"来ます","C":"ください","D":"います"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 17 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N を số lượng (～つ) ください。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 18 (N1 の N2／だれの N2 ですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「これはだれの辞書ですか。」「ランさんのです。」') AS content, _utf8mb4'「だれの」 — Trợ từ の – sở hữu, hỏi của ai.' AS explanation, _utf8mb4'{"options":{"A":"Người hỏi muốn biết từ điển này thuộc về ai. Người đáp cho biết chủ sở hữu là Tanaka.","B":"Người hỏi muốn biết từ điển này thuộc về ai. Người đáp cho biết chủ sở hữu là Lan.","C":"Người hỏi muốn biết từ điển này được mua ở đâu. Người đáp cho biết chủ sở hữu là Lan.","D":"Người hỏi muốn biết ví tiền này thuộc về ai. Người đáp cho biết chủ sở hữu là Lan."},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「これはだれの財布ですか。」「ナムさんのです。」'), _utf8mb4'「だれの」 — Trợ từ の – sở hữu, hỏi của ai.', _utf8mb4'{"options":{"A":"Người hỏi muốn biết đồng hồ này thuộc về ai. Người đáp cho biết chủ sở hữu là Nam.","B":"Người hỏi muốn biết ví tiền này thuộc về ai. Người đáp cho biết chủ sở hữu là Minh.","C":"Người hỏi muốn biết ví tiền này thuộc về ai. Người đáp cho biết chủ sở hữu là Nam.","D":"Người hỏi muốn biết ví tiền này được mua ở đâu. Người đáp cho biết chủ sở hữu là Nam."},"correctAnswer":"C"}'
