) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'いま なんじですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 2 (N は thời gian 1 から thời gian 2 までです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'buổi học bắt đầu lúc 2 giờ sáng và kéo dài đến 5 giờ chiều.', _utf8mb4 0x0a, _utf8mb4'授業は午前二時（　）午後五時までです。') AS content, _utf8mb4'「から」 — Chỉ khoảng thời gian.' AS explanation, _utf8mb4'{"options":{"A":"だけ","B":"よりも","C":"から","D":"まで"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'buổi giới thiệu bắt đầu lúc 6 giờ sáng và kéo dài đến 5 giờ chiều.'), _utf8mb4'「から」 — Chỉ khoảng thời gian.', _utf8mb4'{"options":{"A":"説明会は午前六時まで午後五時までです。","B":"説明会は午前六時だけ午後五時までです。","C":"説明会は午前六時よりも午後五時までです。","D":"説明会は午前六時から午後五時までです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'発表会は午前七時から午後五時までです。'), _utf8mb4'「から」 — Chỉ khoảng thời gian.', _utf8mb4'{"options":{"A":"buổi thuyết trình bắt đầu lúc 7 giờ sáng và kéo dài đến 5 giờ chiều.","B":"buổi thuyết trình kết thúc lúc 7 giờ sáng và kéo dài đến 5 giờ chiều.","C":"buổi học nhóm bắt đầu lúc 7 giờ sáng và kéo dài đến 5 giờ chiều.","D":"buổi thuyết trình bắt đầu lúc 8 giờ sáng và kéo dài đến 5 giờ chiều."},"correctAnswer":"A"}'
