    UNION ALL SELECT 2044, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'buổi học bắt đầu lúc 6 giờ sáng và kéo dài đến 5 giờ chiều.', _utf8mb4 0x0a, _utf8mb4'授業は午前六時（　）午後五時までです。'), CONCAT(_utf8mb4'Chỉ khoảng thời gian. 授業は午前六時から午後五時までです。', _utf8mb4 0x0a, _utf8mb4'buổi học bắt đầu lúc 6 giờ sáng và kéo dài đến 5 giờ chiều.'), _utf8mb4'{"options":{"A":"まで","B":"だけ","C":"よりも","D":"から"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 2 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は thời gian 1 から thời gian 2 までです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 3 (N は いつですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Người hỏi muốn biết khi nào diễn ra buổi học tiếp theo. Câu trả lời là thứ Ba.') AS content, _utf8mb4'「いつ」 — Hỏi thời điểm.' AS explanation, _utf8mb4'{"options":{"A":"「次の授業はどこですか。」「火曜日です。」","B":"「次の授業はだれですか。」「火曜日です。」","C":"「次の授業はいくらですか。」「火曜日です。」","D":"「次の授業はいつですか。」「火曜日です。」"},"correctAnswer":"D"}' AS answers
