    UNION ALL SELECT 2036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ナムさんは図書館で友達と話します。'), CONCAT(_utf8mb4'Trợ từ で – nơi diễn ra hành động. ナムさんは図書館で友達と話します。', _utf8mb4 0x0a, _utf8mb4'Nam nói chuyện với bạn tại thư viện.'), _utf8mb4'{"options":{"A":"Nam nói chuyện với bạn tại thư viện.","B":"Nam nói chuyện với bạn trên đường đến thư viện.","C":"Minh nói chuyện với bạn tại thư viện.","D":"Nam nói chuyện với bạn tại công viên."},"correctAnswer":"A"}'
    UNION ALL SELECT 2050, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Yamada nói chuyện với bạn tại bệnh viện.', _utf8mb4 0x0a, _utf8mb4'山田さんは病院（　）友達と話します。'), CONCAT(_utf8mb4'Trợ từ で – nơi diễn ra hành động. 山田さんは病院で友達と話します。', _utf8mb4 0x0a, _utf8mb4'Yamada nói chuyện với bạn tại bệnh viện.'), _utf8mb4'{"options":{"A":"まで","B":"で","C":"へ","D":"を"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm で N を Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 9 (まいにち／まいあさ／まいばん + Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Tôi học tiếng Nhật mỗi tuần.') AS content, _utf8mb4'「毎」 — Thời gian chỉ thói quen.' AS explanation, _utf8mb4'{"options":{"A":"私は初めての週、日本語を勉強します。","B":"私は毎週、日本語を勉強します。","C":"私は次の週、日本語を勉強します。","D":"私はその週、日本語を勉強します。"},"correctAnswer":"B"}' AS answers
