    UNION ALL SELECT 2037, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tôi chơi quần vợt mỗi năm.', _utf8mb4 0x0a, _utf8mb4'私は（　）年、テニスをします。'), CONCAT(_utf8mb4'Thời gian chỉ thói quen. 私は毎年、テニスをします。', _utf8mb4 0x0a, _utf8mb4'Tôi chơi quần vợt mỗi năm.'), _utf8mb4'{"options":{"A":"初めての","B":"毎","C":"次の","D":"その"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 9 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'まいにち／まいあさ／まいばん + Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 10 (N1 や N2 など)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'朝ご飯には、ケーキやみかんなどを食べます。') AS content, _utf8mb4'「や」 — Trợ từ や～など – liệt kê mở.' AS explanation, _utf8mb4'{"options":{"A":"Bữa sáng tôi ăn những món như bánh mì và quýt.","B":"Bữa sáng tôi ăn những món như bánh ngọt và bánh mì.","C":"Bữa sáng tôi ăn những món như bánh ngọt và quýt.","D":"Bữa sáng tôi ăn duy nhất hai món bánh ngọt và quýt."},"correctAnswer":"C"}' AS answers
