    UNION ALL SELECT 2040, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'An thức dậy lúc 7 giờ sáng mỗi ngày.', _utf8mb4 0x0a, _utf8mb4'アンさんは毎日午前七時（　）起きます。'), CONCAT(_utf8mb4'Trợ từ に – mốc thời gian. アンさんは毎日午前七時に起きます。', _utf8mb4 0x0a, _utf8mb4'An thức dậy lúc 7 giờ sáng mỗi ngày.'), _utf8mb4'{"options":{"A":"で","B":"を","C":"へ","D":"に"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Thời gian に Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 13 (Thời gian 1 から thời gian 2 まで Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'私は午前二時から正午まで練習します。') AS content, _utf8mb4'「まで」 — Khoảng thời gian làm hành động.' AS explanation, _utf8mb4'{"options":{"A":"Tôi luyện tập từ 3 giờ sáng đến buổi trưa.","B":"Tôi luyện tập từ 2 giờ sáng đến buổi trưa.","C":"Tôi bắt đầu luyện tập lúc trưa và kết thúc lúc 2 giờ sáng hôm sau.","D":"Tôi xem phim từ 2 giờ sáng đến buổi trưa."},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tôi làm bài tập từ 6 giờ sáng đến buổi trưa.', _utf8mb4 0x0a, _utf8mb4'私は午前六時から正午（　）宿題をします。'), _utf8mb4'「まで」 — Khoảng thời gian làm hành động.', _utf8mb4'{"options":{"A":"だけ","B":"に","C":"まで","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Tôi phụ việc ở cửa hàng từ 7 giờ sáng đến buổi trưa.'), _utf8mb4'「まで」 — Khoảng thời gian làm hành động.', _utf8mb4'{"options":{"A":"私は午前七時から正午から店を手伝います。","B":"私は午前七時から正午だけ店を手伝います。","C":"私は午前七時から正午に店を手伝います。","D":"私は午前七時から正午まで店を手伝います。"},"correctAnswer":"D"}'
