) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 の + phương hướng + です。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 2 (N のどこですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Lan hỏi đối phương sống ở vùng nào của Thái Lan.', _utf8mb4 0x0a, _utf8mb4'「タイの（　）に住んでいますか」とランさんが尋ねました。') AS content, _utf8mb4'「どこ」 — Hỏi vị trí trong một quốc gia.' AS explanation, _utf8mb4'{"options":{"A":"いつ","B":"どなた","C":"いくつ","D":"どこ"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Nam hỏi đối phương sống ở vùng nào của Pháp.'), _utf8mb4'「どこ」 — Hỏi vị trí trong một quốc gia.', _utf8mb4'{"options":{"A":"「フランスのどこに住んでいますか」とナムさんが尋ねました。","B":"「フランスのいつに住んでいますか」とナムさんが尋ねました。","C":"「フランスのどなたに住んでいますか」とナムさんが尋ねました。","D":"「フランスのいくつに住んでいますか」とナムさんが尋ねました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「中国のどこに住んでいますか」とリンさんが尋ねました。'), _utf8mb4'「どこ」 — Hỏi vị trí trong một quốc gia.', _utf8mb4'{"options":{"A":"Hải hỏi đối phương sống ở vùng nào của Trung Quốc.","B":"Linh hỏi đối phương sống ở vùng nào của Trung Quốc.","C":"Linh hỏi đối phương sống từ năm nào của Trung Quốc.","D":"Linh hỏi đối phương sống ở vùng nào của Hàn Quốc."},"correctAnswer":"B"}'
