    UNION ALL SELECT 2047, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tôi đến rạp phim bằng ô tô.', _utf8mb4 0x0a, _utf8mb4'私は車（　）映画館へ行きます。'), CONCAT(_utf8mb4'Trợ từ で chỉ phương tiện. 私は車で映画館へ行きます。', _utf8mb4 0x0a, _utf8mb4'Tôi đến rạp phim bằng ô tô.'), _utf8mb4'{"options":{"A":"で","B":"へ","C":"を","D":"に"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Phương tiện で Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 6 (N は Aいです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Hiện nay, ngân hàng này có đặc điểm là nhỏ.') AS content, _utf8mb4'「いです」 — Tính từ い – khẳng định.' AS explanation, _utf8mb4'{"options":{"A":"この銀行は小さくないです。","B":"この銀行は小さかったです。","C":"この銀行は小さなです。","D":"この銀行は小さいです。"},"correctAnswer":"D"}' AS answers
