    UNION ALL SELECT 1042, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'thành phố này có đặc điểm là nổi tiếng.', _utf8mb4 0x0a, _utf8mb4'この町は有名（　）。'), CONCAT(_utf8mb4'Tính từ な – khẳng định. この町は有名です。', _utf8mb4 0x0a, _utf8mb4'thành phố này có đặc điểm là nổi tiếng.'), _utf8mb4'{"options":{"A":"くないです","B":"です","C":"なです","D":"いです"},"correctAnswer":"B"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'thành phố cảng có đặc điểm là an toàn.'), CONCAT(_utf8mb4'Tính từ な – khẳng định. 港町は安全です。', _utf8mb4 0x0a, _utf8mb4'thành phố cảng có đặc điểm là an toàn.'), _utf8mb4'{"options":{"A":"港町は安全いです。","B":"港町は安全くないです。","C":"港町は安全です。","D":"港町は安全なです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2007, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'thành phố bên cạnh có đặc điểm là an toàn.', _utf8mb4 0x0a, _utf8mb4'隣の町は安全（　）。'), CONCAT(_utf8mb4'Tính từ な – khẳng định. 隣の町は安全です。', _utf8mb4 0x0a, _utf8mb4'thành phố bên cạnh có đặc điểm là an toàn.'), _utf8mb4'{"options":{"A":"です","B":"なです","C":"いです","D":"くないです"},"correctAnswer":"A"}'
    UNION ALL SELECT 2028, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'thành phố này có đặc điểm là an toàn.'), CONCAT(_utf8mb4'Tính từ な – khẳng định. この町は安全です。', _utf8mb4 0x0a, _utf8mb4'thành phố này có đặc điểm là an toàn.'), _utf8mb4'{"options":{"A":"この町は安全くないです。","B":"この町は安全です。","C":"この町は安全なです。","D":"この町は安全いです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'私の町は便利です。'), CONCAT(_utf8mb4'Tính từ な – khẳng định. 私の町は便利です。', _utf8mb4 0x0a, _utf8mb4'thành phố của tôi có đặc điểm là tiện lợi.'), _utf8mb4'{"options":{"A":"thành phố kia có đặc điểm là tiện lợi.","B":"thành phố của tôi có đặc điểm là bất tiện.","C":"thành phố của tôi có đặc điểm là tiện lợi.","D":"thành phố của tôi không hề tiện lợi."},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は Aな (bỏ な) です。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 8 (Aい → Aくないです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
