    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'ngân hàng này không nhỏ.', _utf8mb4 0x0a, _utf8mb4'この銀行は小さ（　）。') AS content, _utf8mb4'「くないです」 — Tính từ い – phủ định.' AS explanation, _utf8mb4'{"options":{"A":"なです","B":"くないです","C":"いです","D":"かったです"},"correctAnswer":"B"}' AS answers
