    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'港町には道路が多いです。') AS content, _utf8mb4'「が」 — Diễn tả nhiều hoặc ít.' AS explanation, _utf8mb4'{"options":{"A":"Ở thành phố của tôi có nhiều đường sá.","B":"Ở thành phố cảng có nhiều cây.","C":"Ở thành phố cảng có nhiều đường sá.","D":"Ở thành phố cảng có ít đường sá."},"correctAnswer":"C"}' AS answers
