    UNION ALL SELECT 2036, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'thư viện này thoải mái. Người nói cho biết thêm rằng nơi này cũng gần trạm xe buýt.', _utf8mb4 0x0a, _utf8mb4'この図書館は快適です。（　）、バス停からも近いです。'), CONCAT(_utf8mb4'Nối hai câu cùng hướng ý nghĩa. この図書館は快適です。そして、バス停からも近いです。', _utf8mb4 0x0a, _utf8mb4'thư viện này thoải mái. Người nói cho biết thêm rằng nơi này cũng gần trạm xe buýt.'), _utf8mb4'{"options":{"A":"それなのに","B":"そして","C":"しかし","D":"ところが"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 15 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S1。そして、S2。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 16 (S1 が、S2。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ランさんは「この銀行は駅に近いですが、中は意外に静かです」と言いました。') AS content, _utf8mb4'「が」 — Nối hai ý tương phản.' AS explanation, _utf8mb4'{"options":{"A":"Tanaka nhận xét ngân hàng này ở gần ga nhưng bên trong yên tĩnh ngoài dự đoán.","B":"Lan nhận xét ngân hàng này ở gần ga nhưng bên trong yên tĩnh ngoài dự đoán.","C":"Lan nhận xét ngân hàng này ở gần ga nên bên trong yên tĩnh ngoài dự đoán.","D":"Lan nhận xét nhà hát này ở gần ga nhưng bên trong yên tĩnh ngoài dự đoán."},"correctAnswer":"B"}' AS answers
