    UNION ALL SELECT 2035, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Hôm qua Nam đã ăn trưa.', _utf8mb4 0x0a, _utf8mb4'ナムさんは昨日昼ご飯を食べ（　）。'), CONCAT(_utf8mb4'Động từ quá khứ khẳng định. ナムさんは昨日昼ご飯を食べました。', _utf8mb4 0x0a, _utf8mb4'Hôm qua Nam đã ăn trưa.'), _utf8mb4'{"options":{"A":"ません","B":"ましょう","C":"ました","D":"ます"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます → Vました。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 2 (Vません → Vませんでした。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Hôm qua Tanaka đã không học tiếng Nhật.', _utf8mb4 0x0a, _utf8mb4'田中さんは昨日日本語を勉強し（　）。') AS content, _utf8mb4'「ませんでした」 — Động từ quá khứ phủ định.' AS explanation, _utf8mb4'{"options":{"A":"ませんでした","B":"ます","C":"ました","D":"ましょう"},"correctAnswer":"A"}' AS answers
