) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 2 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vません → Vませんでした。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 3 (どこか（へ）Vます／Vましたか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Người nói hỏi Tanaka xem hôm nay có đi đâu đó không.') AS content, _utf8mb4'「どこか」 — Diễn tả đi đâu đó.' AS explanation, _utf8mb4'{"options":{"A":"「田中さん、今日はいつかへ行きましたか。」","B":"「田中さん、今日はどこかへ行きましたか。」","C":"「田中さん、今日はだれかへ行きましたか。」","D":"「田中さん、今日は何かへ行きましたか。」"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「リンさん、先週の日曜日はどこかへ行きましたか。」'), _utf8mb4'「どこか」 — Diễn tả đi đâu đó.', _utf8mb4'{"options":{"A":"Người nói hỏi Hải xem Chủ nhật tuần trước có đi đâu đó không.","B":"Người nói hỏi Linh xem hôm kia có đi đâu đó không.","C":"Người nói hỏi Linh xem Chủ nhật tuần trước có đi đâu đó không.","D":"Người nói hỏi Linh xem Chủ nhật tuần trước có gặp ai đó không."},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Người nói hỏi Hải xem hôm kia có đi đâu đó không.', _utf8mb4 0x0a, _utf8mb4'「ハイさん、一昨日は（　）へ行きましたか。」'), _utf8mb4'「どこか」 — Diễn tả đi đâu đó.', _utf8mb4'{"options":{"A":"だれか","B":"何か","C":"いつか","D":"どこか"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Người nói hỏi An xem năm ngoái có đi đâu đó không.'), _utf8mb4'「どこか」 — Diễn tả đi đâu đó.', _utf8mb4'{"options":{"A":"「アンさん、去年はどこかへ行きましたか。」","B":"「アンさん、去年はだれかへ行きましたか。」","C":"「アンさん、去年は何かへ行きましたか。」","D":"「アンさん、去年はいつかへ行きましたか。」"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「ランさん、去年はどこかへ行きましたか。」'), _utf8mb4'「どこか」 — Diễn tả đi đâu đó.', _utf8mb4'{"options":{"A":"Người nói hỏi Lan xem sáng nay có đi đâu đó không.","B":"Người nói hỏi Lan xem năm ngoái có đi đâu đó không.","C":"Người nói hỏi Lan xem năm ngoái có gặp ai đó không.","D":"Người nói hỏi Tanaka xem năm ngoái có đi đâu đó không."},"correctAnswer":"B"}'
