    UNION ALL SELECT 2038, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Hôm qua tôi ăn trưa cùng với Nam.', _utf8mb4 0x0a, _utf8mb4'昨日、私はナムさん（　）一緒に昼ご飯を食べました。'), CONCAT(_utf8mb4'Làm hành động cùng ai. 昨日、私はナムさんと一緒に昼ご飯を食べました。', _utf8mb4 0x0a, _utf8mb4'Hôm qua tôi ăn trưa cùng với Nam.'), _utf8mb4'{"options":{"A":"へ","B":"と","C":"を","D":"で"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Người と Vます／Vました。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 5 (S1。それから、S2。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Hôm qua tôi làm bài tập. Sau đó tôi nghe nhạc.', _utf8mb4 0x0a, _utf8mb4'昨日は宿題をしました。（　）、音楽を聞きました。') AS content, _utf8mb4'「それから」 — Nối các hành động theo trình tự.' AS explanation, _utf8mb4'{"options":{"A":"ところが","B":"それでも","C":"なぜなら","D":"それから"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Hôm qua tôi đi dạo. Sau đó tôi uống trà.'), _utf8mb4'「それから」 — Nối các hành động theo trình tự.', _utf8mb4'{"options":{"A":"昨日は散歩しました。それから、お茶を飲みました。","B":"昨日は散歩しました。ところが、お茶を飲みました。","C":"昨日は散歩しました。それでも、お茶を飲みました。","D":"昨日は散歩しました。なぜなら、お茶を飲みました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'昨日は料理しました。それから、歌を歌いました。'), _utf8mb4'「それから」 — Nối các hành động theo trình tự.', _utf8mb4'{"options":{"A":"Hôm qua tôi nấu ăn. Sau đó tôi xem ti vi.","B":"Hôm qua tôi nấu ăn. Sau đó tôi hát.","C":"Hôm qua tôi nấu ăn. Trước đó tôi hát.","D":"Hôm qua tôi ăn trưa. Sau đó tôi hát."},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Hôm qua tôi xem phim. Sau đó tôi xem ti vi.', _utf8mb4 0x0a, _utf8mb4'昨日は映画を見ました。（　）、テレビを見ました。'), _utf8mb4'「それから」 — Nối các hành động theo trình tự.', _utf8mb4'{"options":{"A":"それでも","B":"なぜなら","C":"それから","D":"ところが"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Hôm qua tôi học tiếng Nhật. Sau đó tôi xem ti vi.'), _utf8mb4'「それから」 — Nối các hành động theo trình tự.', _utf8mb4'{"options":{"A":"昨日は日本語を勉強しました。ところが、テレビを見ました。","B":"昨日は日本語を勉強しました。それでも、テレビを見ました。","C":"昨日は日本語を勉強しました。なぜなら、テレビを見ました。","D":"昨日は日本語を勉強しました。それから、テレビを見ました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'昨日は宿題をしました。それから、テレビを見ました。'), _utf8mb4'「それから」 — Nối các hành động theo trình tự.', _utf8mb4'{"options":{"A":"Hôm qua tôi làm bài tập. Sau đó tôi xem ti vi.","B":"Hôm qua tôi làm bài tập. Trước đó tôi xem ti vi.","C":"Hôm qua tôi tập thể dục. Sau đó tôi xem ti vi.","D":"Hôm qua tôi làm bài tập. Sau đó tôi gặp bạn."},"correctAnswer":"A"}'
