) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S1。それから、S2。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 6 (Aい → Aかったです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Trước đây ngân hàng này đã từng nhỏ.') AS content, _utf8mb4'「かったです」 — Tính từ い – quá khứ khẳng định.' AS explanation, _utf8mb4'{"options":{"A":"昔、この銀行は小さかったです。","B":"昔、この銀行は小さいです。","C":"昔、この銀行は小さくないです。","D":"昔、この銀行は小さなでした。"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'昔、この交番は明るかったです。'), _utf8mb4'「かったです」 — Tính từ い – quá khứ khẳng định.', _utf8mb4'{"options":{"A":"Trước đây đồn cảnh sát này đã từng tối.","B":"Trước đây đồn cảnh sát này đã từng sáng.","C":"Trước đây đồn cảnh sát này chưa từng sáng.","D":"Trước đây bệnh viện này đã từng sáng."},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Trước đây bệnh viện này đã từng tối.', _utf8mb4 0x0a, _utf8mb4'昔、この病院は暗（　）。'), _utf8mb4'「かったです」 — Tính từ い – quá khứ khẳng định.', _utf8mb4'{"options":{"A":"くないです","B":"なでした","C":"かったです","D":"いです"},"correctAnswer":"C"}'
