    UNION ALL SELECT 2041, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Trước đây bệnh viện này đã không nhỏ.', _utf8mb4 0x0a, _utf8mb4'昔、この病院は小さ（　）。'), CONCAT(_utf8mb4'Tính từ い – quá khứ phủ định. 昔、この病院は小さくなかったです。', _utf8mb4 0x0a, _utf8mb4'Trước đây bệnh viện này đã không nhỏ.'), _utf8mb4'{"options":{"A":"くなかったです","B":"かったです","C":"いです","D":"なでした"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aい → Aくなかったです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 8 (Aな → Aでした。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Mười năm trước, thành phố cảng đã từng nhộn nhịp.', _utf8mb4 0x0a, _utf8mb4'十年前、港町はにぎやか（　）。') AS content, _utf8mb4'「でした」 — Tính từ な – quá khứ khẳng định.' AS explanation, _utf8mb4'{"options":{"A":"かったです","B":"くありません","C":"でした","D":"です"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Mười năm trước, ngôi làng này đã từng bất tiện.'), _utf8mb4'「でした」 — Tính từ な – quá khứ khẳng định.', _utf8mb4'{"options":{"A":"十年前、この村は不便です。","B":"十年前、この村は不便かったです。","C":"十年前、この村は不便くありません。","D":"十年前、この村は不便でした。"},"correctAnswer":"D"}'
