    UNION ALL SELECT 2050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'kỳ nghỉ hè, tôi muốn chơi quần vợt.'), CONCAT(_utf8mb4'Muốn thực hiện hành động. 私は夏休み、テニスをしたいです。', _utf8mb4 0x0a, _utf8mb4'kỳ nghỉ hè, tôi muốn chơi quần vợt.'), _utf8mb4'{"options":{"A":"私は夏休み、テニスをしませんでした。","B":"私は夏休み、テニスをしていました。","C":"私は夏休み、テニスをしたいです。","D":"私は夏休み、テニスをしました。"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 16 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます bỏ ます + たいです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 17 (Địa điểm へ + Vます bỏ ます + に行きます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tanaka đến thư viện để tìm tài liệu.', _utf8mb4 0x0a, _utf8mb4'田中さんは図書館へ資料を探し（　）行きます。') AS content, _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.' AS explanation, _utf8mb4'{"options":{"A":"を","B":"で","C":"の","D":"に"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Linh đến thư viện để gặp bạn.'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"リンさんは図書館へ友達に会いに行きます。","B":"リンさんは図書館へ友達に会いを行きます。","C":"リンさんは図書館へ友達に会いで行きます。","D":"リンさんは図書館へ友達に会いの行きます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ハイさんは図書館へ雑誌を読みに行きます。'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"Hải đến thư viện để gặp giáo viên.","B":"Hải đến thư viện để đọc tạp chí.","C":"Hải đến thư viện sau khi đọc tạp chí.","D":"Mai đến thư viện để đọc tạp chí."},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'An đến thư viện để gặp giáo viên.', _utf8mb4 0x0a, _utf8mb4'アンさんは図書館へ先生に会い（　）行きます。'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"で","B":"の","C":"に","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Lan đến thư viện để gặp giáo viên.'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"ランさんは図書館へ先生に会いを行きます。","B":"ランさんは図書館へ先生に会いで行きます。","C":"ランさんは図書館へ先生に会いの行きます。","D":"ランさんは図書館へ先生に会いに行きます。"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'田中さんは図書館へ先生に会いに行きます。'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"Tanaka đến thư viện để gặp giáo viên.","B":"Tanaka đến thư viện sau khi gặp giáo viên.","C":"Yamada đến thư viện để gặp giáo viên.","D":"Tanaka đến thư viện để mượn sách."},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Linh đến thư viện để đọc tạp chí.', _utf8mb4 0x0a, _utf8mb4'リンさんは図書館へ雑誌を読み（　）行きます。'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"の","B":"に","C":"を","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Nam đến thư viện để học tiếng Nhật.'), _utf8mb4'「に」 — Đi đến đâu để thực hiện hành động.', _utf8mb4'{"options":{"A":"ナムさんは図書館へ日本語を勉強しで行きます。","B":"ナムさんは図書館へ日本語を勉強しの行きます。","C":"ナムさんは図書館へ日本語を勉強しに行きます。","D":"ナムさんは図書館へ日本語を勉強しを行きます。"},"correctAnswer":"C"}'
