) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 17 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm へ + Vます bỏ ます + に行きます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 1 (Vます → Vませんか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'水曜日、一緒に日本語を勉強しませんか。') AS content, _utf8mb4'「ませんか」 — Rủ rê, mời người khác.' AS explanation, _utf8mb4'{"options":{"A":"Vào thứ Tư, người nói mời đối phương cùng học tiếng Nhật.","B":"Vào thứ Tư, người nói thông báo mình đã học tiếng Nhật.","C":"Vào thứ Năm, người nói mời đối phương cùng học tiếng Nhật.","D":"Vào thứ Tư, người nói mời đối phương cùng làm bài tập."},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vào thứ Năm, người nói mời đối phương cùng đọc sách.', _utf8mb4 0x0a, _utf8mb4'木曜日、一緒に本を読み（　）。'), _utf8mb4'「ませんか」 — Rủ rê, mời người khác.', _utf8mb4'{"options":{"A":"ています","B":"ませんか","C":"ませんでした","D":"ました"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Vào thứ Bảy, người nói mời đối phương cùng đi dạo.'), _utf8mb4'「ませんか」 — Rủ rê, mời người khác.', _utf8mb4'{"options":{"A":"土曜日、一緒に散歩しました。","B":"土曜日、一緒に散歩しています。","C":"土曜日、一緒に散歩しませんか。","D":"土曜日、一緒に散歩しませんでした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'日曜日、一緒に料理しませんか。'), _utf8mb4'「ませんか」 — Rủ rê, mời người khác.', _utf8mb4'{"options":{"A":"Vào Chủ nhật, người nói thông báo mình đã nấu ăn.","B":"Vào ngày lễ, người nói mời đối phương cùng nấu ăn.","C":"Vào Chủ nhật, người nói mời đối phương cùng ăn trưa.","D":"Vào Chủ nhật, người nói mời đối phương cùng nấu ăn."},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Vào thứ Hai, người nói mời đối phương cùng ăn trưa.', _utf8mb4 0x0a, _utf8mb4'月曜日、一緒に昼ご飯を食べ（　）。'), _utf8mb4'「ませんか」 — Rủ rê, mời người khác.', _utf8mb4'{"options":{"A":"ませんか","B":"ませんでした","C":"ました","D":"ています"},"correctAnswer":"A"}'
