) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm で Sự kiện があります。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 5 (N が số + 枚 あります。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Ở đây có hai con tem.', _utf8mb4 0x0a, _utf8mb4'ここに切手が二（　）あります。') AS content, _utf8mb4'「枚」 — Trợ số từ 枚（まい）.' AS explanation, _utf8mb4'{"options":{"A":"枚","B":"人","C":"台","D":"匹"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Ở đây có sáu tờ giấy.'), _utf8mb4'「枚」 — Trợ số từ 枚（まい）.', _utf8mb4'{"options":{"A":"ここに紙が六匹あります。","B":"ここに紙が六枚あります。","C":"ここに紙が六人あります。","D":"ここに紙が六台あります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ここに地図が七枚あります。'), _utf8mb4'「枚」 — Trợ số từ 枚（まい）.', _utf8mb4'{"options":{"A":"Ở đây có bảy tấm áp phích.","B":"Ở đây có tám tấm bản đồ.","C":"Ở đây có bảy tấm bản đồ.","D":"Ở đây đã từng có bảy tấm bản đồ."},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Ở đây có tám tấm vé tàu.', _utf8mb4 0x0a, _utf8mb4'ここに切符が八（　）あります。'), _utf8mb4'「枚」 — Trợ số từ 枚（まい）.', _utf8mb4'{"options":{"A":"人","B":"台","C":"匹","D":"枚"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Ở đây có tám tấm ảnh.'), _utf8mb4'「枚」 — Trợ số từ 枚（まい）.', _utf8mb4'{"options":{"A":"ここに写真が八枚あります。","B":"ここに写真が八人あります。","C":"ここに写真が八台あります。","D":"ここに写真が八匹あります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ここに切手が八枚あります。'), _utf8mb4'「枚」 — Trợ số từ 枚（まい）.', _utf8mb4'{"options":{"A":"Ở đây có một con tem.","B":"Ở đây có tám con tem.","C":"Ở đây đã từng có tám con tem.","D":"Ở đây có tám tấm bưu thiếp."},"correctAnswer":"B"}'
