    UNION ALL SELECT 2050, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Ở đây có sáu con tem.', _utf8mb4 0x0a, _utf8mb4'ここに切手が六（　）あります。'), CONCAT(_utf8mb4'Trợ số từ 枚（まい）. ここに切手が六枚あります。', _utf8mb4 0x0a, _utf8mb4'Ở đây có sáu con tem.'), _utf8mb4'{"options":{"A":"匹","B":"枚","C":"人","D":"台"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N が số + 枚 あります。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 6 (N1 で N2 がいちばん Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Trong thực đơn của nhà ăn, Tanaka thích mì udon nhất.') AS content, _utf8mb4'「いちばん」 — So sánh nhất trong một nhóm.' AS explanation, _utf8mb4'{"options":{"A":"田中さんは食堂のメニューの中でうどんがときどき好きです。","B":"田中さんは食堂のメニューの中でうどんがいちばん好きです。","C":"田中さんは食堂のメニューの中でうどんが少し好きです。","D":"田中さんは食堂のメニューの中でうどんがあまり好きです。"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'リンさんは食堂のメニューの中でてんぷらがいちばん好きです。'), _utf8mb4'「いちばん」 — So sánh nhất trong một nhóm.', _utf8mb4'{"options":{"A":"Trong thực đơn của nhà ăn, Hải thích tempura nhất.","B":"Trong thực đơn của nhà ăn, Linh thích cơm nắm nhất.","C":"Trong thực đơn của nhà ăn, Linh thích tempura nhất.","D":"Trong thực đơn của nhà ăn, Linh thích tempura một chút."},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Trong thực đơn của nhà ăn, Hải thích cơm nắm nhất.', _utf8mb4 0x0a, _utf8mb4'ハイさんは食堂のメニューの中でおにぎりが（　）好きです。'), _utf8mb4'「いちばん」 — So sánh nhất trong một nhóm.', _utf8mb4'{"options":{"A":"少し","B":"あまり","C":"ときどき","D":"いちばん"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Trong thực đơn của nhà ăn, An thích mì soba nhất.'), _utf8mb4'「いちばん」 — So sánh nhất trong một nhóm.', _utf8mb4'{"options":{"A":"アンさんは食堂のメニューの中でそばがいちばん好きです。","B":"アンさんは食堂のメニューの中でそばが少し好きです。","C":"アンさんは食堂のメニューの中でそばがあまり好きです。","D":"アンさんは食堂のメニューの中でそばがときどき好きです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'ランさんは食堂のメニューの中でそばがいちばん好きです。'), _utf8mb4'「いちばん」 — So sánh nhất trong một nhóm.', _utf8mb4'{"options":{"A":"Trong thực đơn của nhà ăn, Lan thích mì ramen nhất.","B":"Trong thực đơn của nhà ăn, Lan thích mì soba nhất.","C":"Trong thực đơn của nhà ăn, Lan thích mì soba một chút.","D":"Trong thực đơn của nhà ăn, Tanaka thích mì soba nhất."},"correctAnswer":"B"}'
