) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N のほうが Aです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 9 (どちらも Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Nói về sushi và mì udon, người trả lời thấy cả hai đều ngon.') AS content, _utf8mb4'「どちらも」 — Cả hai đều có cùng đặc điểm.' AS explanation, _utf8mb4'{"options":{"A":"「すしとうどんとどちらがおいしいですか。」「どちらもおいしいです。」","B":"「すしとうどんとどちらがおいしいですか。」「どちらかおいしいです。」","C":"「すしとうどんとどちらがおいしいですか。」「どれをおいしいです。」","D":"「すしとうどんとどちらがおいしいですか。」「何よりおいしいです。」"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「ラーメンとそばとどちらがおいしいですか。」「どちらもおいしいです。」'), _utf8mb4'「どちらも」 — Cả hai đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"Nói về mì ramen và mì udon, người trả lời thấy cả hai đều ngon.","B":"Nói về mì ramen và mì soba, người trả lời thấy cả hai đều ngon.","C":"Nói về mì ramen và mì soba, người trả lời thấy chỉ có một món ngon.","D":"Nói về mì udon và mì soba, người trả lời thấy cả hai đều ngon."},"correctAnswer":"B"}'
