) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 14 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N はどうですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 15 (S + ね。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Tanaka nhắc lại để xác nhận giờ tập trung là 2 giờ.') AS content, _utf8mb4'「ね」 — Trợ từ ね – xác nhận thông tin.' AS explanation, _utf8mb4'{"options":{"A":"「集合は二時です。」「二時ですを。分かりました」と田中さんが確認しました。","B":"「集合は二時です。」「二時ですに。分かりました」と田中さんが確認しました。","C":"「集合は二時です。」「二時ですね。分かりました」と田中さんが確認しました。","D":"「集合は二時です。」「二時ですまで。分かりました」と田中さんが確認しました。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「集合は六時です。」「六時ですね。分かりました」とリンさんが確認しました。'), _utf8mb4'「ね」 — Trợ từ ね – xác nhận thông tin.', _utf8mb4'{"options":{"A":"Linh đề nghị đổi giờ tập trung là 6 giờ.","B":"Hải nhắc lại để xác nhận giờ tập trung là 6 giờ.","C":"Linh nhắc lại để xác nhận giờ tập trung là 7 giờ.","D":"Linh nhắc lại để xác nhận giờ tập trung là 6 giờ."},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'「集合は七時です。」「七時ですね。分かりました」とハイさんが確認しました。'), _utf8mb4'「ね」 — Trợ từ ね – xác nhận thông tin.', _utf8mb4'{"options":{"A":"Hải nhắc lại để xác nhận giờ tập trung là 7 giờ.","B":"Hải đề nghị đổi giờ tập trung là 7 giờ.","C":"Mai nhắc lại để xác nhận giờ tập trung là 7 giờ.","D":"Hải nhắc lại để xác nhận giờ tập trung là 8 giờ."},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'An nhắc lại để xác nhận giờ tập trung là 8 giờ.'), _utf8mb4'「ね」 — Trợ từ ね – xác nhận thông tin.', _utf8mb4'{"options":{"A":"「集合は八時です。」「八時ですに。分かりました」とアンさんが確認しました。","B":"「集合は八時です。」「八時ですね。分かりました」とアンさんが確認しました。","C":"「集合は八時です。」「八時ですまで。分かりました」とアンさんが確認しました。","D":"「集合は八時です。」「八時ですを。分かりました」とアンさんが確認しました。"},"correctAnswer":"B"}'
