    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Lan tìm nhưng không có gì ở vị trí trên kệ.', _utf8mb4 0x0a, _utf8mb4'ランさんが探しましたが、棚の上には（　）ありませんでした。') AS content, _utf8mb4'「何も」 — Phủ định hoàn toàn với なにも.' AS explanation, _utf8mb4'{"options":{"A":"いつも","B":"何も","C":"だれも","D":"どこも"},"correctAnswer":"B"}' AS answers
