    UNION ALL SELECT 2050, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Hải tìm nhưng không có gì ở vị trí trong túi.', _utf8mb4 0x0a, _utf8mb4'ハイさんが探しましたが、袋の中には（　）ありませんでした。'), CONCAT(_utf8mb4'Phủ định hoàn toàn với なにも. ハイさんが探しましたが、袋の中には何もありませんでした。', _utf8mb4 0x0a, _utf8mb4'Hải tìm nhưng không có gì ở vị trí trong túi.'), _utf8mb4'{"options":{"A":"どこも","B":"いつも","C":"何も","D":"だれも"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'なにもありません。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 6 (Vます → Vて)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Trong ghi chú của Tanaka, cần viết dạng て của động từ “đọc”.') AS content, _utf8mb4'「読んで」 — Chuyển động từ sang thể て.' AS explanation, _utf8mb4'{"options":{"A":"田中さんのメモ「読みます → 読んでください」。","B":"田中さんのメモ「読みます → 読んでいます」。","C":"田中さんのメモ「読みます → 読んで」。","D":"田中さんのメモ「読みます → 読みます」。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'山田さんのメモ「遊びます → 遊んで」。'), _utf8mb4'「遊んで」 — Chuyển động từ sang thể て.', _utf8mb4'{"options":{"A":"Trong ghi chú của Yamada, cần viết dạng phủ định của động từ “chơi”.","B":"Trong ghi chú của Kimura, cần viết dạng て của động từ “chơi”.","C":"Trong ghi chú của Yamada, cần viết dạng て của động từ “ăn”.","D":"Trong ghi chú của Yamada, cần viết dạng て của động từ “chơi”."},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Trong ghi chú của Linh, cần viết dạng て của động từ “nói”.', _utf8mb4 0x0a, _utf8mb4'リンさんのメモ「話します → （　）」。'), _utf8mb4'「話して」 — Chuyển động từ sang thể て.', _utf8mb4'{"options":{"A":"話して","B":"話します","C":"話してください","D":"話しています"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Trong ghi chú của Hải, cần viết dạng て của động từ “xem”.'), _utf8mb4'「見て」 — Chuyển động từ sang thể て.', _utf8mb4'{"options":{"A":"ハイさんのメモ「見ます → 見ています」。","B":"ハイさんのメモ「見ます → 見て」。","C":"ハイさんのメモ「見ます → 見ます」。","D":"ハイさんのメモ「見ます → 見てください」。"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'アンさんのメモ「待ちます → 待って」。'), _utf8mb4'「待って」 — Chuyển động từ sang thể て.', _utf8mb4'{"options":{"A":"Trong ghi chú của Lan, cần viết dạng て của động từ “đợi”.","B":"Trong ghi chú của An, cần viết dạng て của động từ “chơi”.","C":"Trong ghi chú của An, cần viết dạng て của động từ “đợi”.","D":"Trong ghi chú của An, cần viết dạng phủ định của động từ “đợi”."},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Trong ghi chú của Lan, cần viết dạng て của động từ “đợi”.', _utf8mb4 0x0a, _utf8mb4'ランさんのメモ「待ちます → （　）」。'), _utf8mb4'「待って」 — Chuyển động từ sang thể て.', _utf8mb4'{"options":{"A":"待ちます","B":"待ってください","C":"待っています","D":"待って"},"correctAnswer":"D"}'
