) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 11 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'どれですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 12 (Vています。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Ngay bây giờ Tanaka đang hát.') AS content, _utf8mb4'「います」 — Hành động đang diễn ra.' AS explanation, _utf8mb4'{"options":{"A":"今、田中さんは歌を歌っています。","B":"今、田中さんは歌を歌っていました。","C":"今、田中さんは歌を歌ってください。","D":"今、田中さんは歌を歌ってからです。"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'今、リンさんは音楽を聞いています。'), _utf8mb4'「います」 — Hành động đang diễn ra.', _utf8mb4'{"options":{"A":"Ngay bây giờ Linh đang chụp ảnh.","B":"Ngay bây giờ Linh đang nghe nhạc.","C":"Ngay bây giờ Linh vừa mới ngừng nghe nhạc.","D":"Ngay bây giờ Hải đang nghe nhạc."},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Ngay bây giờ Hải đang chụp ảnh.', _utf8mb4 0x0a, _utf8mb4'今、ハイさんは写真を撮って（　）。'), _utf8mb4'「います」 — Hành động đang diễn ra.', _utf8mb4'{"options":{"A":"ください","B":"からです","C":"います","D":"いました"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Ngay bây giờ An đang vẽ tranh.'), _utf8mb4'「います」 — Hành động đang diễn ra.', _utf8mb4'{"options":{"A":"今、アンさんは絵を描いていました。","B":"今、アンさんは絵を描いてください。","C":"今、アンさんは絵を描いてからです。","D":"今、アンさんは絵を描いています。"},"correctAnswer":"D"}'
