) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vています。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 13 (Vます → Vましょうか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'田中さん、私が写真を撮りましょうか。') AS content, _utf8mb4'「ましょうか」 — Chủ động đề nghị giúp đỡ.' AS explanation, _utf8mb4'{"options":{"A":"Tôi chủ động đề nghị mở cửa giúp Tanaka.","B":"Tôi chủ động đề nghị chụp ảnh giúp Tanaka.","C":"Tôi báo đã chụp ảnh xong cho Tanaka.","D":"Tôi chủ động đề nghị chụp ảnh giúp Yamada."},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tôi chủ động đề nghị khiêng bàn giúp Linh.', _utf8mb4 0x0a, _utf8mb4'リンさん、私が机を運び（　）。'), _utf8mb4'「ましょうか」 — Chủ động đề nghị giúp đỡ.', _utf8mb4'{"options":{"A":"ませんでした","B":"ています","C":"ましょうか","D":"ました"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu tương ứng.', _utf8mb4 0x0a, _utf8mb4'Tôi chủ động đề nghị bật đèn giúp Hải.'), _utf8mb4'「ましょうか」 — Chủ động đề nghị giúp đỡ.', _utf8mb4'{"options":{"A":"ハイさん、私が電気をつけました。","B":"ハイさん、私が電気をつけませんでした。","C":"ハイさん、私が電気をつけています。","D":"ハイさん、私が電気をつけましょうか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này có nghĩa gì?', _utf8mb4 0x0a, _utf8mb4'アンさん、私が切符を買いましょうか。'), _utf8mb4'「ましょうか」 — Chủ động đề nghị giúp đỡ.', _utf8mb4'{"options":{"A":"Tôi chủ động đề nghị mua vé giúp An.","B":"Tôi báo đã mua vé xong cho An.","C":"Tôi chủ động đề nghị mua vé giúp Lan.","D":"Tôi chủ động đề nghị mang hành lý giúp An."},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Điền chỗ trống.', _utf8mb4 0x0a, _utf8mb4'Tôi chủ động đề nghị mua vé giúp Lan.', _utf8mb4 0x0a, _utf8mb4'ランさん、私が切符を買い（　）。'), _utf8mb4'「ましょうか」 — Chủ động đề nghị giúp đỡ.', _utf8mb4'{"options":{"A":"ています","B":"ましょうか","C":"ました","D":"ませんでした"},"correctAnswer":"B"}'
