    UNION ALL SELECT 1049, _utf8mb4'EASY', _utf8mb4'「学校の名前」 có nghĩa gì trong tiếng Việt?', _utf8mb4'学校の名前 (がっこうのなまえ) nghĩa là “tên trường”.', _utf8mb4'{"options":["đi du học","sách của tôi","lữ khách","tên trường"],"correctAnswer":"tên trường"}', _utf8mb4'学'
