    UNION ALL SELECT 1054, _utf8mb4'EASY', _utf8mb4'「私立大学」 (đại học tư thục) được đọc như thế nào bằng hiragana?', _utf8mb4'私立大学 (しりつだいがく) nghĩa là “đại học tư thục”.', _utf8mb4'{"options":["わたしのがっこう","じんこう","ごさい","しりつだいがく"],"correctAnswer":"しりつだいがく"}', _utf8mb4'学'
