    UNION ALL SELECT 1115, _utf8mb4'EASY', _utf8mb4'「才能」 (tài năng) được đọc như thế nào bằng hiragana?', _utf8mb4'才能 (さいのう) nghĩa là “tài năng”.', _utf8mb4'{"options":["がっこう","がくせいしょう","だいがくせい","さいのう"],"correctAnswer":"さいのう"}', _utf8mb4'才'
