    UNION ALL SELECT 79, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「なんじ」 với nghĩa “mấy giờ”.', _utf8mb4'何時 (なんじ) nghĩa là “mấy giờ”.', _utf8mb4'{"options":["四年","四時","何時","何年生"],"correctAnswer":"何時"}', _utf8mb4'時'
    UNION ALL SELECT 80, _utf8mb4'EASY', _utf8mb4'「何年生」 có nghĩa gì trong tiếng Việt?', _utf8mb4'何年生 (なんねんせい) nghĩa là “học sinh năm thứ mấy”.', _utf8mb4'{"options":["một năm","năm ngoái","bảy giờ","học sinh năm thứ mấy"],"correctAnswer":"học sinh năm thứ mấy"}', _utf8mb4'年'
