    UNION ALL SELECT 1053, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「すいようび」 với nghĩa “thứ tư”.', _utf8mb4'水曜日 (すいようび) nghĩa là “thứ tư”.', _utf8mb4'{"options":["土曜日","満月","水曜日","木曜日"],"correctAnswer":"水曜日"}', _utf8mb4'水'
    UNION ALL SELECT 1054, _utf8mb4'EASY', _utf8mb4'「木曜日」 có nghĩa gì trong tiếng Việt?', _utf8mb4'木曜日 (もくようび) nghĩa là “thứ năm”.', _utf8mb4'{"options":["thứ sáu","chủ nhật","tháng trước","thứ năm"],"correctAnswer":"thứ năm"}', _utf8mb4'木'
    UNION ALL SELECT 1055, _utf8mb4'MEDIUM', _utf8mb4'Điền chữ Hán vào ô □ trong 「□曜日」 để được từ đọc là 「きんようび」 (thứ sáu).', _utf8mb4'金曜日 (きんようび) nghĩa là “thứ sáu”.', _utf8mb4'{"options":["金","土","曜","何"],"correctAnswer":"金"}', _utf8mb4'金'
    UNION ALL SELECT 1056, _utf8mb4'HARD', _utf8mb4'Chọn cách đọc lần lượt của 「土曜日」 và 「水泳」.', _utf8mb4'土曜日 (どようび) nghĩa là “thứ bảy”. 水泳 (すいえい) nghĩa là “môn bơi lội”.', _utf8mb4'{"options":["すいえい ／ どようび","どようび ／ すいえい","どようび ／ にちようび","つきみ ／ すいえい"],"correctAnswer":"どようび ／ すいえい"}', _utf8mb4'土'
    UNION ALL SELECT 1057, _utf8mb4'HARD', _utf8mb4'Hai từ nào lần lượt mang nghĩa “chủ nhật” và “uống nước”?', _utf8mb4'日曜日 (にちようび) nghĩa là “chủ nhật”. 水を飲む (みずをのむ) nghĩa là “uống nước”.', _utf8mb4'{"options":["満月 ／ 水を飲む","水を飲む ／ 日曜日","日曜日 ／ 水を飲む","日曜日 ／ 何曜日"],"correctAnswer":"日曜日 ／ 水を飲む"}', _utf8mb4'曜'
