    UNION ALL SELECT 78, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「こくさい」 với nghĩa “quốc tế”.', _utf8mb4'国際 (こくさい) nghĩa là “quốc tế”.', _utf8mb4'{"options":["女の人","国際","国旗","男の子"],"correctAnswer":"国際"}', _utf8mb4'国'
    UNION ALL SELECT 79, _utf8mb4'EASY', _utf8mb4'「国旗」 có nghĩa gì trong tiếng Việt?', _utf8mb4'国旗 (こっき) nghĩa là “quốc kỳ”.', _utf8mb4'{"options":["nam sinh viên","bé gái","quốc kỳ","người đàn ông"],"correctAnswer":"quốc kỳ"}', _utf8mb4'国'
    UNION ALL SELECT 80, _utf8mb4'MEDIUM', _utf8mb4'Điền chữ Hán vào ô □ trong 「□の人」 để được từ đọc là 「おとこのひと」 (người đàn ông).', _utf8mb4'男の人 (おとこのひと) nghĩa là “người đàn ông”.', _utf8mb4'{"options":["女","区","市","男"],"correctAnswer":"男"}', _utf8mb4'男'
    UNION ALL SELECT 81, _utf8mb4'HARD', _utf8mb4'Chọn cách đọc lần lượt của 「男の子」 và 「地区」.', _utf8mb4'男の子 (おとこのこ) nghĩa là “bé trai”. 地区 (ちく) nghĩa là “khu vực”.', _utf8mb4'{"options":["おとこのこ ／ ちく","おとこのこ ／ だんしがくせい","じなん ／ ちく","ちく ／ おとこのこ"],"correctAnswer":"おとこのこ ／ ちく"}', _utf8mb4'男'
    UNION ALL SELECT 82, _utf8mb4'HARD', _utf8mb4'Hai từ nào lần lượt mang nghĩa “nam sinh viên” và “trong quận”?', _utf8mb4'男子学生 (だんしがくせい) nghĩa là “nam sinh viên”. 区内 (くない) nghĩa là “trong quận”.', _utf8mb4'{"options":["区内 ／ 男子学生","男子学生 ／ 区内","男子学生 ／ 長男","女の人 ／ 区内"],"correctAnswer":"男子学生 ／ 区内"}', _utf8mb4'男'
