    UNION ALL SELECT 1124, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「あとから」 với nghĩa “sau đó”.', _utf8mb4'後から (あとから) nghĩa là “sau đó”.', _utf8mb4'{"options":["後から","見る","見物","食堂"],"correctAnswer":"後から"}', _utf8mb4'後'
