    UNION ALL SELECT 1129, _utf8mb4'EASY', _utf8mb4'「野生」 có nghĩa gì trong tiếng Việt?', _utf8mb4'野生 (やせい) nghĩa là “trạng thái hoang dã”.', _utf8mb4'{"options":["bán đảo","trạng thái hoang dã","một giờ rưỡi","nửa giá"],"correctAnswer":"trạng thái hoang dã"}', _utf8mb4'野'
    UNION ALL SELECT 1130, _utf8mb4'MEDIUM', _utf8mb4'Điền chữ Hán vào ô □ trong 「一時□」 để được từ đọc là 「いちじはん」 (một giờ rưỡi).', _utf8mb4'一時半 (いちじはん) nghĩa là “một giờ rưỡi”.', _utf8mb4'{"options":["小","肉","半","大"],"correctAnswer":"半"}', _utf8mb4'半'
    UNION ALL SELECT 1131, _utf8mb4'HARD', _utf8mb4'Chọn cách đọc lần lượt của 「半年」 và 「大雨」.', _utf8mb4'半年 (はんとし) nghĩa là “nửa năm”. 大雨 (おおあめ) nghĩa là “mưa to”.', _utf8mb4'{"options":["はんとし ／ はんがく","はんぶんずつ ／ おおあめ","おおあめ ／ はんとし","はんとし ／ おおあめ"],"correctAnswer":"はんとし ／ おおあめ"}', _utf8mb4'半'
    UNION ALL SELECT 1132, _utf8mb4'HARD', _utf8mb4'Hai từ nào lần lượt mang nghĩa “nửa giá” và “rất thích”?', _utf8mb4'半額 (はんがく) nghĩa là “nửa giá”. 大好き (だいすき) nghĩa là “rất thích”.', _utf8mb4'{"options":["半額 ／ 大好き","半額 ／ 半日","半そで ／ 大好き","大好き ／ 半額"],"correctAnswer":"半額 ／ 大好き"}', _utf8mb4'半'
    UNION ALL SELECT 1133, _utf8mb4'EASY', _utf8mb4'「半日」 (nửa ngày) được đọc như thế nào bằng hiragana?', _utf8mb4'半日 (はんにち) nghĩa là “nửa ngày”.', _utf8mb4'{"options":["たいかい","はんにち","はんぶんずつ","はんとう"],"correctAnswer":"はんにち"}', _utf8mb4'半'
    UNION ALL SELECT 1134, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「はんぶんずつ」 với nghĩa “mỗi bên một nửa”.', _utf8mb4'半分ずつ (はんぶんずつ) nghĩa là “mỗi bên một nửa”.', _utf8mb4'{"options":["大きい","大声","半分ずつ","半そで"],"correctAnswer":"半分ずつ"}', _utf8mb4'半'
